// Validate settings and build the Actor input. Fails early (before any paid work) on bad settings.
const s = $('Job watch settings').first().json;
const boards = String(s.leverBoards || '')
  .split(/[\n,]+/).map(x => x.trim()).filter(Boolean)
  .map(x => { const m = x.match(/jobs\.lever\.co\/([^\/?#\s]+)/i); return (m ? m[1] : x).toLowerCase(); });
if (!boards.length) throw new Error('Add at least one Lever board slug (e.g. the "acme" in jobs.lever.co/acme).');
const badSlug = boards.filter(b => !/^[a-z0-9][a-z0-9._-]*$/.test(b));
if (badSlug.length) throw new Error('Not valid Lever board slugs: ' + badSlug.join(', '));
if (/eu\.lever\.co/i.test(String(s.leverBoards))) throw new Error('EU-hosted Lever boards (jobs.eu.lever.co) are not supported.');
if (!s.spreadsheetId || /YOUR_/i.test(s.spreadsheetId)) {
  throw new Error('Set spreadsheetId in "Job watch settings" (the long ID in your Google Sheet URL).');
}
const minSalary = Math.max(0, Number(s.minSalary) || 0);
const currency = String(s.salaryCurrency || 'USD').toUpperCase();
const intervals = ['per-year-salary', 'per-month-salary', 'per-week-salary', 'per-day-wage', 'per-hour-wage'];
const interval = String(s.salaryInterval || 'per-year-salary');
if (!intervals.includes(interval)) throw new Error('salaryInterval must be one of: ' + intervals.join(', '));
const actorInput = {
  boards: [...new Set(boards)].slice(0, 20),
  salaryOnly: true,                 // only postings that publish a numeric salary
  maxResults: Math.max(1, Math.min(Number(s.maxJobsPerRun) || 25, 1000)),
  remoteOnly: Boolean(s.remoteOnly),
  minSalary,
  salaryCurrency: currency,
  salaryInterval: interval,
};
return [{ json: {
  actorInput,
  spreadsheetId: String(s.spreadsheetId).trim(),
  sheetName: String(s.sheetName || 'Salary watch'),
  slackChannel: String(s.slackChannel || '#jobs'),
  maxCostPerRunUsd: Number(s.maxCostPerRunUsd) || 0.1,
} }];

// Keep postings not yet in the sheet and format their salary range.
const seen = new Set($input.all().map(i => String(i.json.jobId || '').trim()).filter(Boolean));
const jobs = $('Fetch Lever jobs with salaries').all().map(i => i.json)
  .filter(j => j && j.id && j.salaryMin != null);
const per = { 'per-year-salary': 'year', 'per-month-salary': 'month', 'per-week-salary': 'week', 'per-day-wage': 'day', 'per-hour-wage': 'hour' };
const fmt = n => (n == null || n === '') ? '' : Number(n).toLocaleString('en-US');
const now = new Date().toISOString();
const out = [];
for (const j of jobs) {
  const key = String(j.id);
  if (seen.has(key)) continue;
  seen.add(key);
  const range = j.salaryMax != null && j.salaryMax !== j.salaryMin
    ? `${j.salaryCurrency || ''} ${fmt(j.salaryMin)}-${fmt(j.salaryMax)}` : `${j.salaryCurrency || ''} ${fmt(j.salaryMin)}`;
  out.push({ json: {
    jobId: key,
    board: j.board || '',
    title: j.title || '',
    team: j.team || '',
    department: j.department || '',
    location: j.location || '',
    workplaceType: j.workplaceType || '',
    commitment: j.commitment || '',
    salaryMin: j.salaryMin,
    salaryMax: j.salaryMax ?? '',
    salaryCurrency: j.salaryCurrency || '',
    salaryInterval: j.salaryInterval || '',
    salaryRange: `${range.trim()} per ${per[j.salaryInterval] || j.salaryInterval || '?'}`,
    postedAt: j.createdAt || '',
    jobUrl: j.url || '',
    firstSeenAt: now,
  } });
}
// Highest paying first, so the Slack digest leads with them.
out.sort((a, b) => (Number(b.json.salaryMax || b.json.salaryMin) || 0) - (Number(a.json.salaryMax || a.json.salaryMin) || 0));
return out; // empty -> nothing is written or posted

// One Slack message per run, not one per job.
const rows = $input.all().map(i => i.json);
const top = rows.slice(0, 15).map(r =>
  `- <${r.jobUrl}|${r.title}> (${r.board}, ${r.location || 'location n/a'}${r.workplaceType ? ', ' + r.workplaceType : ''}): ${r.salaryRange}`);
const more = rows.length > 15 ? `\n...and ${rows.length - 15} more in the sheet.` : '';
return [{ json: { text: `*${rows.length} new Lever job${rows.length === 1 ? '' : 's'} with published salary*\n${top.join('\n')}${more}` } }];
